'use strict'

// Regression test for:
// AssertionError [ERR_ASSERTION]: false == true
//   at handleConnectError (lib/dispatcher/client.js)
//
// The ERR_TLS_CERT_ALTNAME_INVALID branch of handleConnectError asserted
// `client[kRunning] === 0`, which assumes pipelining === 1. With pipelining > 1
// there can be in-flight (running) requests when the connect error fires, and
// the assertion crashed the process instead of erroring the requests.
//
// Fix: drain running requests first (mirroring onError/onSocketClose), then
// drain the pending ones.

const { test } = require('node:test')
const assert = require('node:assert')
const { Client } = require('..')
const {
  kQueue,
  kRunningIdx,
  kPendingIdx,
  kRunning,
  kPending
} = require('../lib/core/symbols')

test('ERR_TLS_CERT_ALTNAME_INVALID errors running requests when pipelining > 1', async () => {
  const err = Object.assign(new Error('Hostname/IP does not match certificate'), {
    code: 'ERR_TLS_CERT_ALTNAME_INVALID'
  })

  let client
  client = new Client('https://localhost:1', {
    pipelining: 10,
    connect (opts, callback) {
      // Simulate requests that were already written to the wire, i.e. what
      // pipelining allows: kRunning = kPendingIdx - kRunningIdx > 0.
      client[kPendingIdx] = client[kQueue].length
      assert.ok(client[kRunning] > 0, 'expected in-flight requests')

      callback(err)
    }
  })

  const results = await Promise.allSettled(
    Array.from({ length: 5 }, () => client.request({ path: '/', method: 'GET' }))
  )

  for (const result of results) {
    assert.strictEqual(result.status, 'rejected')
    assert.strictEqual(result.reason.code, 'ERR_TLS_CERT_ALTNAME_INVALID')
  }

  assert.strictEqual(client[kRunning], 0)
  assert.strictEqual(client[kPending], 0)

  await client.close()
})

